const medias = $input.all();

// O IF pode separar mídias locais e externas. A posição no lote original
// deixa de corresponder à posição das mídias que chegam a este node.
return medias.map((item, index) => {
  const media = item.json;
  let post;
  try {
    post = $('Recupera | Contexto Post').itemMatching(index).json;
  } catch (error) {
    throw new Error(`Contexto do post não vinculado à mídia de entrada ${index}: ${error.message}`);
  }

  // Proteção adicional contra associação incorreta
  if (Number(media.id) !== Number(post.wp_media_id)) {
    throw new Error(
      `Mídia incompatível: esperado ${post.wp_media_id}, recebido ${media.id}`
    );
  }

  return {
    json: {
      // CONTROLE
      migration_id: post.migration_id,
      ordem: post.ordem,
      status_migracao: post.status_migracao,

      // POST
      post_id: post.post_id,
      post_date: post.post_date,
      post_modified: post.post_modified,
      post_slug: post.post_slug,
      post_link: post.post_link,

      // FEATURED MEDIA
      wp_media_id: media.id,
      media_date: media.date,
      media_slug: media.slug,
      mime_type: media.mime_type,

      // ARQUIVO ORIGINAL
      original_url: media.source_url,
      original_file: media.media_details?.file ?? null,
      original_width: media.media_details?.width ?? null,
      original_height: media.media_details?.height ?? null,
      original_filesize: media.media_details?.filesize ?? null
    }
  };
});

const contexto = $('Monta | Candidatos [5]').first().json;
if (!Array.isArray(contexto.candidatos) || contexto.candidatos.length === 0) {
  throw new Error('Reserva recebeu página sem candidatos; checkpoint não pode ser fechado.');
}
const id = (value, field) => {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number <= 0) throw new Error(`${field} inválido: ${value}`);
  return number;
};
const esperados = new Set(contexto.candidatos.map(c =>
  `${id(c.post_id, 'post_id candidato')}:${id(c.wp_media_id, 'wp_media_id candidato')}`
));
const metadata = new Set(['fieldCount', 'affectedRows', 'insertId', 'info', 'serverStatus', 'warningStatus', 'changedRows']);
const wrappers = ['json', 'rows', 'result', 'results', 'data', 'resultset', 'resultsets'];
const rows = [];
function collect(value, depth = 0) {
  if (depth > 10) throw new Error('Resultset da reserva aninhado além do limite esperado');
  if (Array.isArray(value)) { value.forEach(v => collect(v, depth + 1)); return; }
  if (!value || typeof value !== 'object') throw new Error('Retorno da reserva em formato inválido');
  const keys = Object.keys(value);
  if (keys.some(k => ['migration_id', 'post_id', 'wp_media_id', 'status'].includes(k))) {
    rows.push(value);
    return;
  }
  const nested = [...wrappers, ...keys.filter(k => /^\d+$/.test(k))].filter(k => k in value);
  if (nested.length) { nested.forEach(k => collect(value[k], depth + 1)); return; }
  if (keys.length && !keys.every(k => metadata.has(k))) {
    throw new Error(`Retorno da reserva desconhecido: ${keys.join(', ')}`);
  }
}
$input.all().forEach(item => collect(item.json));
const reservados = new Map();
for (const row of rows) {
  const migrationId = id(row.migration_id, 'migration_id');
  const postId = id(row.post_id, 'post_id');
  const mediaId = id(row.wp_media_id, 'wp_media_id');
  const ordem = id(row.ordem, 'ordem');
  if (row.status !== 'PROCESSING') throw new Error(`Migration ${migrationId} retornou status ${row.status}`);
  if (!esperados.has(`${postId}:${mediaId}`)) throw new Error(`Migration ${migrationId} fora dos candidatos da página`);
  const previous = reservados.get(migrationId);
  if (previous && (previous.post_id !== postId || previous.wp_media_id !== mediaId)) {
    throw new Error(`Migration ${migrationId} retornou contexto conflitante`);
  }
  reservados.set(migrationId, {migration_id: migrationId, ordem, post_id: postId, wp_media_id: mediaId,
    status: row.status, created_at: row.created_at ?? null, updated_at: row.updated_at ?? null});
}
const page = {
  pagina_processada: id(contexto.pagina_processada, 'pagina_processada'),
  per_page: id(contexto.per_page, 'per_page'),
  ultimo_post_pagina: id(contexto.ultimo_post_pagina, 'ultimo_post_pagina'),
  total_candidatos: contexto.candidatos.length
};
if (reservados.size === 0) {
  // Só o resultado do checkpoint determina se a página foi resolvida.
  return [{json: {tem_reserva: false, total_reservado: 0,
    etapa: 'SEM_CANDIDATOS_ELEGIVEIS', ...page}}];
}
return [...reservados.values()].sort((a, b) => a.ordem - b.ordem).map(row => ({
  json: {tem_reserva: true, total_reservado: reservados.size, ...row, ...page}
}));

const reservados = $input.all();
const posts = $('Busca Posts').all();

// Índice dos posts originalmente retornados pelo WordPress
const postsMap = new Map(
  posts.map(item => [
    Number(item.json.id),
    item.json
  ])
);

return reservados.map(item => {

  const reserva = item.json;
  const post = postsMap.get(Number(reserva.post_id));

  if (!post) {
    throw new Error(
      `Post ${reserva.post_id} não encontrado no resultado de Busca Posts`
    );
  }

  return {
    json: {
      // CONTROLE DA MIGRAÇÃO
      migration_id: reserva.migration_id,
      ordem: reserva.ordem,
      status_migracao: reserva.status,

      // POST WORDPRESS
      post_id: reserva.post_id,
      wp_media_id: reserva.wp_media_id,

      post_date: post.date,
      post_modified: post.modified,
      post_slug: post.slug,
      post_link: post.link
    }
  };
});

// SUB | Storage Media External retorna o provider escolhido pela reserva.
const upload = $json;
const origem = $('Loop').item.json;
const id = Number(origem.migration_id);
if (!id || !Number(origem.post_id) || !Number(origem.wp_media_id)) {
  throw new Error('Contexto da migration incompleto no Loop.');
}
const provider = String(upload.provider || '').toLowerCase();
if (!provider || provider.length > 100) {
  throw new Error(`Migration ${id}: provider ausente ou inválido.`);
}
const key = String(upload.public_id || '').trim();
const url = String(upload.secure_url || '').trim();
const sha256 = String(upload.sha256 || key.split('/').pop() || '').toLowerCase();
if (!/^[a-f0-9]{64}$/.test(sha256) || !key) {
  throw new Error(`Migration ${id}: SHA-256 ou chave do objeto ausente.`);
}
if (!/^https:\/\/[^\s/?#]+\/[^\s]*$/i.test(url)) {
  throw new Error(`Migration ${id}: URL pública inválida.`);
}
return {json: {
  migration_id: id,
  ordem: Number(origem.ordem),
  post_id: Number(origem.post_id),
  wp_media_id: Number(origem.wp_media_id),
  original_url: origem.original_url ?? null,
  original_file: origem.original_file ?? null,
  sha256,
  storage_provider: provider,
  storage_key: key,
  storage_url: url,
  storage_asset_id: upload.asset_id ?? null,
  storage_bytes: upload.bytes ?? null,
  storage_width: upload.width ?? null,
  storage_height: upload.height ?? null,
  storage_mime_type: upload.mime_type ?? null,
  cloudinary_public_id: provider === 'cloudinary' ? key : null,
  cloudinary_url: provider === 'cloudinary' ? url : null,
  cloudinary_asset_id: provider === 'cloudinary' ? upload.asset_id ?? null : null,
  upload_ok: true
}};

const items = $input.all();
if (!items.length) throw new Error('Nenhum resultado de upload recebido do Loop.');
const uploads = items.map((item, index) => {
  const row = item.json;
  const id = Number(row.migration_id);
  if (!id || row.upload_ok !== true) {
    throw new Error(`Item ${index + 1}: migration_id ou upload_ok inválido.`);
  }
  // Compatibilidade para retomar a execução 469–471 já enviada ao storage.
  const url = String(row.storage_url || row.cloudinary_url || '').trim();
  const key = String(row.storage_key || row.cloudinary_public_id || '').trim();
  const inferred = /^https:\/\/res\.cloudinary\.com\//i.test(url)
    ? 'cloudinary' : /^https:\/\/[^/]+\.r2\.dev\//i.test(url) ? 'cloudflare_r2' : null;
  const provider = String(row.storage_provider || row.provider || inferred || '').toLowerCase();
  const sha256 = String(row.sha256 || '').toLowerCase();
  if (!provider || provider.length > 100 ||
      !/^https:\/\/[^\s/?#]+\/[^\s]*$/i.test(url) ||
      !/^[a-f0-9]{64}$/.test(sha256) || !key) {
    throw new Error(`Migration ${id}: contrato de storage inválido.`);
  }
  const extension = url.match(/\.(jpe?g|png|webp)(?:\?|$)/i)?.[1].toLowerCase();
  return {
    migration_id: id, post_id: Number(row.post_id), wp_media_id: Number(row.wp_media_id),
    original_url: row.original_url, sha256,
    storage_provider: provider, storage_key: key, storage_url: url,
    storage_asset_id: row.storage_asset_id ?? row.cloudinary_asset_id ?? null,
    storage_bytes: row.storage_bytes ?? row.cloudinary_bytes ?? null,
    storage_width: row.storage_width ?? row.cloudinary_width ?? null,
    storage_height: row.storage_height ?? row.cloudinary_height ?? null,
    storage_mime_type: row.storage_mime_type ?? (extension ? `image/${extension === 'jpg' ? 'jpeg' : extension}` : null),
    cloudinary_cloud_name: provider === 'cloudinary' ? url.match(/^https:\/\/res\.cloudinary\.com\/([^/]+)\//i)?.[1] : null,
    cloudinary_public_id: provider === 'cloudinary' ? key : null,
    cloudinary_url: provider === 'cloudinary' ? url : null,
    cloudinary_asset_id: provider === 'cloudinary' ? row.cloudinary_asset_id ?? row.storage_asset_id ?? null : null,
    cloudinary_bytes: provider === 'cloudinary' ? row.cloudinary_bytes ?? row.storage_bytes ?? null : null,
    cloudinary_width: provider === 'cloudinary' ? row.cloudinary_width ?? row.storage_width ?? null : null,
    cloudinary_height: provider === 'cloudinary' ? row.cloudinary_height ?? row.storage_height ?? null : null,
    cloudinary_format: provider === 'cloudinary' ? row.cloudinary_format ?? null : null
  };
});
if (new Set(uploads.map(x => x.migration_id)).size !== uploads.length) {
  throw new Error('migration_id duplicado no lote de uploads.');
}
return [{json: {total_uploads: uploads.length, uploads}}];

const lote = $('Monta | Lote Uploads').first().json;
const checkpoint = $('Monta | Candidatos [5]').first().json;

// ---------------------------------------------------------
// 1. Valida lote Storage
// ---------------------------------------------------------

if (!lote?.uploads || !Array.isArray(lote.uploads)) {
  throw new Error('Lote de uploads Storage não encontrado.');
}

if (lote.uploads.length === 0) {
  throw new Error('Lote Storage vazio.');
}

// ---------------------------------------------------------
// 2. Valida contexto da página / checkpoint
// ---------------------------------------------------------

const paginaProcessada = Number(checkpoint.pagina_processada);
const ultimoPostPagina = Number(checkpoint.ultimo_post_pagina);

if (!paginaProcessada) {
  throw new Error('pagina_processada inválida ou não encontrada.');
}

if (!ultimoPostPagina) {
  throw new Error('ultimo_post_pagina inválido ou não encontrado.');
}

if (
  !Array.isArray(checkpoint.candidatos) ||
  checkpoint.candidatos.length === 0
) {
  throw new Error('Lista candidatos da página não encontrada.');
}

// Normaliza o contrato que será enviado ao subfluxo
const candidatosPagina = checkpoint.candidatos.map(item => ({
  post_id: Number(item.post_id),
  wp_media_id: Number(item.wp_media_id)
}));

// ---------------------------------------------------------
// 3. Recupera lote Storage
// ---------------------------------------------------------

const mapa = new Map();

for (const row of lote.uploads) {
  const migrationId = Number(row.migration_id);

  if (!migrationId) {
    throw new Error('migration_id inválido no lote Storage.');
  }

  mapa.set(migrationId, {
    migration_id: migrationId,
    post_id: Number(row.post_id),
    wp_media_id_original: Number(row.wp_media_id),

    original_url: row.original_url,
    sha256: row.sha256,

    storage_provider: row.storage_provider,
    storage_key: row.storage_key,
    storage_url: row.storage_url,
    storage_asset_id: row.storage_asset_id ?? null,
    storage_mime_type: row.storage_mime_type ?? null,
    cloudinary_cloud_name: row.cloudinary_cloud_name,
    cloudinary_public_id: row.cloudinary_public_id,
    cloudinary_url: row.cloudinary_url,
    cloudinary_asset_id: row.cloudinary_asset_id ?? null,

    width: row.storage_width ?? null,
    height: row.storage_height ?? null,
    format: row.storage_mime_type?.split("/")[1] ?? null,

    // -----------------------------------------------------
    // Contexto da página para fechamento do checkpoint
    // -----------------------------------------------------
    pagina_processada: paginaProcessada,
    ultimo_post_pagina: ultimoPostPagina,
    candidatos_pagina: candidatosPagina
  });
}

// ---------------------------------------------------------
// 4. Retorno para o Sub Fluxo
// ---------------------------------------------------------

return [...mapa.values()]
  .sort((a, b) => a.migration_id - b.migration_id)
  .map(row => ({ json: row }));

