CALL SP_WP_registra_midia_externa(
    {{ $('Recupera | Contexto Post').item.json.migration_id }},
    {{ $('Recupera | Contexto Post').item.json.post_id }},
    {{ $('Recupera | Contexto Post').item.json.wp_media_id }},
    '{{ ($json.source_url || '').replace(/'/g, "''") }}'
