parameters.jsCode:
const posts = $input.all();

// Recupera o checkpoint que originou esta busca
const checkpoint = $('DB | Ponteiro Migração').first().json;

const candidatos = posts
  .filter(item =>
    item.json.id &&
    item.json.featured_media &&
    Number(item.json.featured_media) > 0
  )
  .map(item => ({
    post_id: Number(item.json.id),
    wp_media_id: Number(item.json.featured_media)
  }));

// Último post efetivamente recebido nesta página.
// Importante: usa todos os posts da página, não apenas os candidatos
// que possuem featured_media.
const ultimoPostPagina = posts.length
  ? Number(posts[posts.length - 1].json.id)
  : null;

// Limite operacional controlado pelo banco
const limiteExecucao = Number(checkpoint.limite_execucao);

if (!limiteExecucao || limiteExecucao < 1) {
  throw new Error(
    `limite_execucao inválido no checkpoint: ${checkpoint.limite_execucao}`
  );
}

return [
  {
    json: {
      candidatos,

      // Quantidade máxima que a SP poderá reservar nesta execução
      limite: limiteExecucao,

      total_candidatos: candidatos.length,

      pagina_processada: Number(checkpoint.pagina_atual),

      // Tamanho da página consultada no WordPress
      per_page: Number(checkpoint.per_page),

      // Mantido também para rastreabilidade
      limite_execucao: limiteExecucao,

      ultimo_post_pagina: ultimoPostPagina
    }
  }
];

const origem = $('Monta | Candidatos [5]').first().json;

if (!Array.isArray(origem.candidatos) || origem.candidatos.length === 0) {
  throw new Error('Candidatos da página não encontrados.');
}

if (!origem.pagina_processada) {
  throw new Error('pagina_processada não encontrada.');
}

if (!origem.ultimo_post_pagina) {
  throw new Error('ultimo_post_pagina não encontrado.');
}

return [
  {
    json: {
      candidatos: origem.candidatos.map(item => ({
        post_id: Number(item.post_id),
        wp_media_id: Number(item.wp_media_id)
      })),

      pagina_processada: Number(origem.pagina_processada),
      ultimo_post_pagina: Number(origem.ultimo_post_pagina),

      total_candidatos: origem.candidatos.length
    }
  }
];

// Executado depois de SP | Fecha Checkpoint no PAI. Não altera o banco.
const rows = [];
const wrappers = ['json', 'rows', 'result', 'results', 'data', 'resultset', 'resultsets'];
function collect(value, depth = 0) {
  if (depth > 10) throw new Error('Resultado do checkpoint aninhado além do limite esperado');
  if (Array.isArray(value)) { value.forEach(v => collect(v, depth + 1)); return; }
  if (!value || typeof value !== 'object') return;
  if (Object.prototype.hasOwnProperty.call(value, 'resultado')) { rows.push(value); return; }
  const numericKeys = Object.keys(value).filter(k => /^\d+$/.test(k));
  [...wrappers, ...numericKeys].filter(k => k in value).forEach(k => collect(value[k], depth + 1));
}
$input.all().forEach(item => collect(item.json));
if (rows.length !== 1) throw new Error(`Checkpoint retornou ${rows.length} resultados funcionais; esperado 1.`);
const row = rows[0];
const count = (value, field) => {
  const number = Number(value);
  if (!Number.isSafeInteger(number) || number < 0) throw new Error(`${field} inválido: ${value}`);
  return number;
};
const total = count(row.total_candidatos, 'total_candidatos');
const resolvidos = count(row.total_resolvidos, 'total_resolvidos');
const pagina = count(row.pagina_atual, 'pagina_atual');
if (total === 0 || resolvidos > total) throw new Error('Contagem inválida no checkpoint Featured');
const semReserva = $('Normaliza | Lote Reservado').first().json.tem_reserva === false;
if (row.resultado === 'AGUARDANDO' && semReserva) {
  throw new Error(`Página Featured ${pagina} bloqueada: 0 reservas e ${resolvidos}/${total} candidatos resolvidos. Inspecione o retorno de SP | Reserva Lote e os estados em WP_migracao_featured; não avance o checkpoint manualmente.`);
}
if (!['AGUARDANDO', 'AVANCADO', 'JA_AVANCADO'].includes(row.resultado)) {
  throw new Error(`Resultado de checkpoint desconhecido: ${row.resultado}`);
}
if (row.resultado !== 'AGUARDANDO' && resolvidos !== total) {
  throw new Error(`Checkpoint ${row.resultado} inconsistente: ${resolvidos}/${total} resolvidos`);
}
return [{json: {resultado: row.resultado, total_candidatos: total,
  total_resolvidos: resolvidos, pagina_atual: pagina, ultimo_post_id: row.ultimo_post_id ?? null,
  sem_reserva: semReserva}}];
